"""Data for the campus builds, climate annexes, LOD stage plan, campus builder tool and BIM project briefs.
Own words, brand neutral: no supplier, maker, landlord or person names, no prices, no addresses.
Every number is a planning value worked out from tools/campus_bim_data.py (module about 14 m2, studio rule 30 seats, and so on).
Status: reference designs v0.1, draft for the owner's review. A licensed local engineer and the local authority confirm every real project."""

MODULE_M2 = 14          # plan area of one module (2.4 m x 5.8 m)
SOLAR_KW_PER_ROOF_MODULE = 1.2   # planning value, only where the structure allows
GLASS_M2_PER_STUDIO = 5.5        # standard asks for 5 to 6 m2 of glass per studio
FOLD_M2 = 15                     # one folding partition across a module length (5.8 m x 2.6 m)

# One campus type = a list of spaces. Each space: (name, group, count, modules each, seats each, learner seats?, rooms each, wet?)
# "learner seats" is True when the seats count towards learners taught at one time.
def S(name, group, count, mods, seats=0, learn=False, rooms=1, wet=False):
    return dict(name=name, group=group, count=count, mods=mods, seats=seats, learn=learn, rooms=rooms, wet=wet)

